package io.lumine.mythic.lib.skill.handler;
import io.lumine.mythic.lib.skill.SkillMetadata; import io.lumine.mythic.lib.skill.parameter.SkillParameter; import io.lumine.mythic.lib.skill.parameter.value.ScalingFormula; import io.lumine.mythic.lib.skill.result.SkillResult; import io.lumine.mythic.lib.skill.trigger.TriggerType; import java.text.DecimalFormat; import java.util.*;
public abstract class SkillHandler<T extends SkillResult> { private final String id; private final Map<String,SkillParameter> params=new LinkedHashMap<>(); private final Set<String> modifiers=new LinkedHashSet<>(); public SkillHandler(){this("skill");} public SkillHandler(boolean ignored){this("skill");} public SkillHandler(String id){this.id=id==null?"skill":id;} public String getId(){return id;} public String getLowerCaseId(){return id.toLowerCase(Locale.ROOT);} public String getName(){return id;} public List<String> getLore(){return List.of();} public List<String> getCategories(){return List.of();} public TriggerType getDefaultTriggerType(){return TriggerType.CAST;} public boolean isTriggerable(){return true;} public void addParameter(String id,SkillParameter p){params.put(id,p);} public String getParameterName(String id){return id;} public double getDefaultItemParameter(String id){SkillParameter p=params.get(id);return p==null?0:p.getItemDefaultValue();} public ScalingFormula getDefaultFormula(String id){SkillParameter p=params.get(id);return p==null?ScalingFormula.ZERO:p.getScalingFormula();} public DecimalFormat getParameterDecimalFormat(String id){SkillParameter p=params.get(id);return p==null?new DecimalFormat("0.##"):p.getDecimalFormat();} public void registerModifiers(String... ids){modifiers.addAll(Arrays.asList(ids));} public void registerModifiers(Collection<String> ids){modifiers.addAll(ids);} public Set<String> getParameters(){return Set.copyOf(params.keySet());} public abstract T getResult(SkillMetadata metadata); public abstract void whenCast(T result,SkillMetadata metadata); public Set<String> getModifiers(){return Set.copyOf(modifiers);} public List<String> getUiLore(){return getLore();} @Override public boolean equals(Object o){return o instanceof SkillHandler<?> h&&id.equalsIgnoreCase(h.id);}@Override public int hashCode(){return id.toLowerCase(Locale.ROOT).hashCode();} }
